function Build-CrossQueueFault32Tests {
    param([Parameter(Mandatory)][string]$Directory,[Parameter(Mandatory)][ValidateSet(4,6)][int]$IpVersion,
        [ValidateSet('iso','ms')][string]$Mode='iso',[switch]$Guarded)
    if(![IO.Path]::IsPathFullyQualified($Directory)){throw 'Cross queue fault output must be absolute'}
    if($script:SourceFingerprint -cnotmatch '^[a-f0-9]{64}$'){throw 'Cross queue fault requires shipping fingerprint'}
    New-Item -ItemType Directory -Path $Directory -Force|Out-Null;$utf8=[Text.UTF8Encoding]::new($false)
    $inputs=@();$hosts=[ordered]@{'tests/model/drain_boundary_tests.c'='50753c442cbeaaaa3956cc27d9884cb93fbe316a42953f387514f530466bc4a8';'tests/model/kernel_nbl_fixture.h'='c236a169004e4851111c1000353b85685dbe92b32191e8cb28509989f19d0eb3'}
    foreach($relative in $hosts.Keys){$source=Join-Path $script:RepoRoot $relative;if((Get-FileHash $source).Hash.ToLowerInvariant()-cne$hosts[$relative]){throw "Cross queue frozen host changed:$relative"};$copy=Join-Path $Directory ('original-'+[IO.Path]::GetFileName($relative));[IO.File]::WriteAllBytes($copy,[IO.File]::ReadAllBytes($source));$inputs+=@{relative=$relative;source=$source;source_sha256=$hosts[$relative];path=$copy;sha256=(Get-FileHash $copy).Hash.ToLowerInvariant()}}
    $generated=@();$completion=Join-Path $Directory 'completion-observe.h'
    $lines=@('static PB_RESULT CqPush(PB_QUEUE_VIEW *,const PB_DESCRIPTOR *,uint32_t,uint32_t,uint32_t,uint32_t *,uint32_t *);','#define PbQueuePushRing CqPush',('#include "'+(Join-Path $script:RepoRoot 'driver/v2/session_completion.h').Replace('\','/')+'"'),'#undef PbQueuePushRing')
    [IO.File]::WriteAllText($completion,($lines -join "`n")+"`n",$utf8);$generated+=@{name='completion-observer';path=$completion;sha256=(Get-FileHash $completion).Hash.ToLowerInvariant()}
    $query=Join-Path $Directory 'query-observe.h';$lines=@('static VOID CqQueryAcquire(KSPIN_LOCK *,KLOCK_QUEUE_HANDLE *);','#define KeAcquireInStackQueuedSpinLock CqQueryAcquire',('#include "'+(Join-Path $script:RepoRoot 'driver/v2/session_query.h').Replace('\','/')+'"'),'#undef KeAcquireInStackQueuedSpinLock')
    [IO.File]::WriteAllText($query,($lines -join "`n")+"`n",$utf8);$generated+=@{name='query-observer';path=$query;sha256=(Get-FileHash $query).Hash.ToLowerInvariant()}
    function Convert-CqIncludes([string]$Text,[string]$Source){return [regex]::Replace($Text,'"([^"\r\n]*\.[ch])"',{param($m)$p=$m.Groups[1].Value;if(![IO.Path]::IsPathFullyQualified($p)){$p=[IO.Path]::GetFullPath((Join-Path (Split-Path $Source) $p))};'"'+$p.Replace('\','/')+'"'})}
    $kernelSource=Join-Path $script:RepoRoot 'tests/model/kernel_nbl_fixture.h';$body=[IO.File]::ReadAllText($kernelSource);$marker='#include "../../driver/v2/session_completion.h"'
    if([regex]::Matches($body,[regex]::Escape($marker)).Count-ne1){throw 'Cross queue completion include must be unique'}
    $body=$body.Replace($marker,('#include "'+$completion.Replace('\','/')+'"'));$kernel=Join-Path $Directory 'kernel-host.h';[IO.File]::WriteAllText($kernel,(Convert-CqIncludes $body $kernelSource),$utf8);$generated+=@{name='kernel';path=$kernel;sha256=(Get-FileHash $kernel).Hash.ToLowerInvariant()}
    $hostSource=Join-Path $script:RepoRoot 'tests/model/drain_boundary_tests.c';$body=[IO.File]::ReadAllText($hostSource);$marker='#include "kernel_nbl_fixture.h"'
    if([regex]::Matches($body,[regex]::Escape($marker)).Count-ne1){throw 'Cross queue kernel include must be unique'}
    $body=$body.Replace($marker,('#include "'+$kernel.Replace('\','/')+'"'));$hostPath=Join-Path $Directory 'drain-host.h';[IO.File]::WriteAllText($hostPath,(Convert-CqIncludes $body $hostSource),$utf8);$generated+=@{name='drain';path=$hostPath;sha256=(Get-FileHash $hostPath).Hash.ToLowerInvariant()}
    $production=@();foreach($relative in @(rg --files driver common include)){$relative=$relative.Replace('\','/');$source=Join-Path $script:RepoRoot $relative;$copy=Join-Path $Directory ('source-'+$relative.Replace('/','-'));[IO.File]::WriteAllBytes($copy,[IO.File]::ReadAllBytes($source));$production+=@{relative=$relative;source=$source;source_sha256=(Get-FileHash $source).Hash.ToLowerInvariant();path=$copy;sha256=(Get-FileHash $copy).Hash.ToLowerInvariant()}};if($LASTEXITCODE){throw 'Cross queue production enumeration failed'}
    $test=Join-Path $script:RepoRoot 'tests/model/cross_queue_fault32_tests.c';$lines=@();if($Guarded){$lines+='#define PB_GUARD_TESTS 1'};$lines+='#define PB_TEST_IP_VERSION '+$IpVersion;$bindings=[ordered]@{PB_CQ_HOST=$hostPath;PB_QUERY_SOURCE=$query};foreach($name in $bindings.Keys){$lines+='#define '+$name+' "'+$bindings[$name].Replace('\','/')+'"'};$lines+='#include "'+$test.Replace('\','/')+'"'
    $entry=Join-Path $Directory 'entry.c';[IO.File]::WriteAllText($entry,($lines -join "`n")+"`n",$utf8)
    $flags=@('/nologo','/std:c17','/MT','/O2','/W4','/WX','/DNDEBUG','/D_WIN32_WINNT=0x0601','/DWINVER=0x0601','/DNTDDI_VERSION=0x06010000',"/volatile:$Mode","/Fo$Directory\")+@($script:VersionArguments|Where-Object {$_ -notlike '/DPB_SOURCE_FINGERPRINT=*'})+"/DPB_SOURCE_FINGERPRINT=$script:SourceFingerprint"
    $exe=Join-Path $Directory 'cross-queue-fault32.exe';Invoke-BuildTool cl.exe ($flags+@($entry,'common/v2_core.c','common/ethernet.c','common/coalesce.c','common/packet.c','/link',"/out:$exe"))|Out-Host
    return [ordered]@{path=$exe;sha256=(Get-FileHash $exe).Hash.ToLowerInvariant();entry=$entry;entry_sha256=(Get-FileHash $entry).Hash.ToLowerInvariant();test=$test;test_sha256=(Get-FileHash $test).Hash.ToLowerInvariant();mode=$Mode;guarded=[bool]$Guarded;ip_version=$IpVersion;ndebug=$true;pb_api_tests=$false;arguments=$flags;inputs=$inputs;generated=$generated;production=$production}
}
